@Test
void timelineCursorGenerationChangesOnlyWhenExistingHistoryChanges() {
    var store = new MemoryHostStore();
    store.create("session-1", new ModelRef("faux", "faux-1"), ".", Instant.EPOCH);
    SessionDocument first = store.update("session-1", 0, document -> document.appendEntry(
            "main", "message-1", SessionDocument.EntryKind.MESSAGE,
            Optional.of(new io.github.diodeme.ji.ai.Message("message-1",
                    io.github.diodeme.ji.ai.Message.Role.USER,
                    List.of(new io.github.diodeme.ji.ai.Content.Text("one")), Instant.EPOCH)),
            Map.of(), Instant.EPOCH));
    SessionDocument second = store.update("session-1", first.revision(), document -> document.appendEntry(
            "main", "message-2", SessionDocument.EntryKind.MESSAGE,
            Optional.of(new io.github.diodeme.ji.ai.Message("message-2",
                    io.github.diodeme.ji.ai.Message.Role.ASSISTANT,
                    List.of(new io.github.diodeme.ji.ai.Content.Text("two")), Instant.EPOCH)),
            Map.of(), Instant.EPOCH));
    HostStore.TimelinePage current = store.timeline("session-1",
            new HostStore.TimelineQuery(java.util.OptionalLong.empty(), 1));
    store.update("session-1", second.revision(), document -> document.appendEntry(
            "main", "message-3", SessionDocument.EntryKind.MESSAGE,
            Optional.of(new io.github.diodeme.ji.ai.Message("message-3",
                    io.github.diodeme.ji.ai.Message.Role.USER,
                    List.of(new io.github.diodeme.ji.ai.Content.Text("three")), Instant.EPOCH)),
            Map.of(), Instant.EPOCH));
    assertEquals("one", store.timeline("session-1", new HostStore.TimelineQuery(
            current.olderSequence(), java.util.OptionalLong.of(current.generation()), 1))
            .items().getFirst().message().text());

    SessionDocument latest = store.load("session-1").orElseThrow();
    store.update("session-1", latest.revision(), document -> document.moveLane(
            "main", Optional.of("message-1")));
    assertThrows(IllegalArgumentException.class, () -> store.timeline(
            "session-1", new HostStore.TimelineQuery(
                    current.olderSequence(), java.util.OptionalLong.of(current.generation()), 1)));
}

